import { timestamp, uuid } from 'drizzle-orm/pg-core';

/** Shared column helpers (DATABASE.md §2). Ids are UUIDv7 generated by the application. */
export const id = () => uuid().primaryKey();
export const merchantId = () => uuid().notNull();
export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();
export const updatedAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();
